        /// <summary>
        /// kthen datarow trupi dokumenti sipas idse se trupit te dokumentit
        /// </summary>
        ///<param name="idShitjeTrupi"> trupi i dokumentit te shitjes nga merret id</param>
        ///<returns>nje datarow me te gjithe trupin e dokumentit te shitjes te kesaj id  </returns>
        internal DataRow ktheTrupiShitjeSipasID(int idShitjeTrupi)
        {
            ImbLogger.LogTraceShitje($"Filloi metoda ktheTrupiShitjeSipasID sipas id shitje trupi : {idShitjeTrupi}");
            dbManager.Open();
            dbManager.CreateParameters(1);
            dbManager.AddParameters(0, "@IDSHITJETRUPI", idShitjeTrupi, ParameterDirection.Input);
            DataSet ds = dbManager.ExecuteDataSet(CommandType.StoredProcedure, "prc_T_TRUPISHITJE_sel");

            if (ds == null)
            {
                ImbLogger.LogWarningShitje($"Metoda ktheTrupiShitjeSipasID sipas id shitje trupi : {idShitjeTrupi} ktheu null.");
                return null;
            }

            if (ds.Tables[0].Rows.Count == 0 || ds.Tables[0].Rows.Count > 1)
            {
                ImbLogger.LogWarningShitje($"Metoda ktheTrupiShitjeSipasID sipas id shitje trupi : {idShitjeTrupi} ktheu null.");
                return null;
            }
            ImbLogger.LogTraceShitje($"Filloi metoda ktheTrupiShitjeSipasID sipas id shitje trupi : {idShitjeTrupi}");
            return ds.Tables[0].Rows[0];

        }

