            dbManager.AddParameters(3, "@DTDOK", dtdok, ParameterDirection.Input);
            dbManager.AddParameters(4, "@IDNDERMARJE", idNdermarrje, ParameterDirection.Input);
            DataSet ds = dbManager.ExecuteDataSet(CommandType.StoredProcedure, "prc_T_KOKAMAGAZINA_ekzistonRegjistrimMagazine");
