        /// <summary>
        /// ekzekuton prc_T_KOKAMAGAZINA_ins ne DB dhe kthen statusin e perfundimit te ekzekutimit te SP-se perkatese
        /// Shiko clsMesazh brenda ketij moduli per informacion te metejshem mbi vleren e kthimit te kesaj metode
        /// <param name="dtDk"> data e dokumentit te magazines</param>
        /// <param name="dtRegj"> data e regjistrimit te dokumentit te magazines</param>
        /// <param name="idKDok"> id kategorise se dokumentit me te cilin lidhet.</param>
        /// <param name="idKlFurn"> id e klient furnitorit me te cilin lidhet</param>
        /// <param name="idKonf"> id e konfigurimit te dokumentit</param>
        /// <param name="idLidhes">id e dokumentit nga e cila gjenerohet ne rastet e modifikimit </param>
        /// <param name="idllojdokmag"> id e llojit te dokumentit</param>
        /// <param name="idMag">id e magazines</param>
        /// <param name="idMagKoka">id ritese e kokes se magazines</param>
        /// <param name="idNder"> id e ndermarjes</param>
        /// <param name="idNdVt"> id e ndermarje vitit</param>
        /// <param name="idNiv"> id e nivelit te regjistrimit</param>
        /// <param name="idPer"> id e perdoruesit se e ben regjistrimin</param>
        /// <param name="idProj"> id e projektit ne te cilin ben pjese</param>
        /// <param name="idrenditjes"> id e renditjes per te renditur dokumentat e te njejtes date sipas kohes se regjistrimit</param>
        /// <param name="idSt"> id e statusit te dokumentit</param>
        /// <param name="nrDk">nr i dokumentit</param>
        /// <param name="nrProj"> nr i projektit</param>
        /// <param name="shenim"> shenime </param>
        /// <param name="vl"> vlera totale e dokumentit</param>
        /// <param name="idGjenerues">id e dokumentit nga gjenerohet magazina nga nje ambjent tjeter</param>
        /// <param name="idKonfigGjenerues">id e konfigurimit nga gjenerohet dokumenti</param>
        /// <param name="idNivelGjenerues">id e nivelit nga gjenerohet dokumenti</param>
        /// <returns> nje objekt clsMesazh qe tregon nese ruajtja eshte kryer ne rregull apo jo.</returns>
        /// </summary>
        internal int ruajKokaInventarizim(int idKoka, int idNiv, int idKonf, int idMag, DateTime dtDk, string nrDk, int idLidhes, int idSt, int idNder, int idNdVt, int idPer, DateTime dtRegj, int idNivelGjenerues, int idKonfigGjenerues, int idGjenerues, string pershkrimi, int idkrijuesi, int idrap)
        {

            dbManager.Open();
            dbManager.CreateParameters(18);
            dbManager.AddParameters(0, "@IDKOKA", idKoka, ParameterDirection.Output);
            dbManager.AddParameters(1, "@IDNIVEL", idNiv, ParameterDirection.Input);
            dbManager.AddParameters(2, "@IDKONFIGAMBJENTE", idKonf, ParameterDirection.Input);

            if (idMag == 0 || idMag == -1)
                dbManager.AddParameters(3, "@IDMAG", DBNull.Value, ParameterDirection.Input);
            else
                dbManager.AddParameters(3, "@IDMAG", idMag, ParameterDirection.Input);
            dbManager.AddParameters(4, "@NRDOK", nrDk, ParameterDirection.Input);
            dbManager.AddParameters(5, "@DTDOK", dtDk, ParameterDirection.Input);
            if (idLidhes == 0)
                dbManager.AddParameters(6, "@IDDOKNGA", DBNull.Value, ParameterDirection.Input);
            else
                dbManager.AddParameters(6, "@IDDOKNGA", idLidhes, ParameterDirection.Input);
            dbManager.AddParameters(7, "@IDSTATUSDOK", idSt, ParameterDirection.Input);
            dbManager.AddParameters(8, "@IDNDERMarje", idNder, ParameterDirection.Input);
            dbManager.AddParameters(9, "@IDNDERVITi", idNdVt, ParameterDirection.Input);
            dbManager.AddParameters(10, "@IDPERDORUESI", idPer, ParameterDirection.Input);
            dbManager.AddParameters(11, "@DTREGJ", dtRegj, ParameterDirection.Input);
            if (idNivelGjenerues == 0)
                dbManager.AddParameters(12, "@IDNIVELGJENERUES", DBNull.Value, ParameterDirection.Input);
            else
                dbManager.AddParameters(12, "@IDNIVELGJENERUES", idNivelGjenerues, ParameterDirection.Input);
            if (idKonfigGjenerues == 0)
                dbManager.AddParameters(13, "@IDKONFIGGJENERUES", DBNull.Value, ParameterDirection.Input);
            else
                dbManager.AddParameters(13, "@IDKONFIGGJENERUES", idKonfigGjenerues, ParameterDirection.Input);
            if (idGjenerues == 0)
                dbManager.AddParameters(14, "@IDGJENERUES", DBNull.Value, ParameterDirection.Input);
            else
                dbManager.AddParameters(14, "@IDGJENERUES", idGjenerues, ParameterDirection.Input);

            if (pershkrimi == "")
                dbManager.AddParameters(15, "@Pershkrimi", DBNull.Value, ParameterDirection.Input);
            else
                dbManager.AddParameters(15, "@Pershkrimi", pershkrimi, ParameterDirection.Input);

            dbManager.AddParameters(16, "@IDKRIJUESI", idkrijuesi, ParameterDirection.Input);
            if (idrap == 0)
                dbManager.AddParameters(17, "@IDRAPORTDESIGN", DBNull.Value, ParameterDirection.Input);
            else
                dbManager.AddParameters(17, "@IDRAPORTDESIGN", idrap, ParameterDirection.Input);

            dbManager.ExecuteNonQuery(CommandType.StoredProcedure, "prc_T_KOKAINVENTARIZIM_ins");
            idKoka = int.Parse(dbManager.Parameters[0].Value.ToString());
            clsMesazh mesazh = new clsMesazh(true, MessagesResource.Messages["mesazhRuajtjeMeSukses"]);
            return idKoka;

        }

