        /// </summary>
        internal clsMesazh modifikoKokaInventarizim(int idKoka, int idNiv, int idKonf, int idMag, DateTime dtDk, string nrDk, int idSt, int idPer, DateTime dtRegj, string pershkrimi, int idrap)
        {

            dbManager.Open();
            dbManager.CreateParameters(11);
            dbManager.AddParameters(0, "@IDKOKA", idKoka, ParameterDirection.Input);
            dbManager.AddParameters(1, "@IDNIVEL", idNiv, ParameterDirection.Input);
