        public DataView ktheTeDhenaPivotGrid(string kolonatString, int idNdermarje, string kodModul, int shikoGjitheDokumentet, int idPerdoruesi, int gjuha, string kodKubi, int idNdermVit, string data)
        {
            string emriSp = "";

            switch (kodModul)
            {
                case "M_KONTABILITETI":
                    emriSp = "PivotGrid_Kontabiliteti";
                    dbManager.CreateParameters(2);
                    dbManager.AddParameters(0, "@IDNDERMARJE", idNdermarje, ParameterDirection.Input);
                    dbManager.AddParameters(1, "@fushat", kolonatString, ParameterDirection.Input);
                    break;
                case "M_SHITJE":
                    emriSp = "PivotGrid";
                    dbManager.CreateParameters(4);
                    dbManager.AddParameters(0, "@IDNDERMARJE", idNdermarje, ParameterDirection.Input);
                    dbManager.AddParameters(1, "@shikoGjitheDokumentat", shikoGjitheDokumentet, ParameterDirection.Input);
                    dbManager.AddParameters(2, "@idPerdoruesi", idPerdoruesi, ParameterDirection.Input);
                    dbManager.AddParameters(3, "@fushat", kolonatString, ParameterDirection.Input);
                    break;
                case "M_BLERJE":
                    emriSp = "PivotGrid_Blerje";
                    dbManager.CreateParameters(4);
                    dbManager.AddParameters(0, "@IDNDERMARJE", idNdermarje, ParameterDirection.Input);
                    dbManager.AddParameters(1, "@shikoGjitheDokumentat", shikoGjitheDokumentet, ParameterDirection.Input);
                    dbManager.AddParameters(2, "@idPerdoruesi", idPerdoruesi, ParameterDirection.Input);
                    dbManager.AddParameters(3, "@fushat", kolonatString, ParameterDirection.Input);
                    break;
                case "M_INVENTAR":
                    emriSp = "PivotGrid_Magazina";
                    dbManager.CreateParameters(2);
                    dbManager.AddParameters(0, "@IDNDERMARJE", idNdermarje, ParameterDirection.Input);
                    dbManager.AddParameters(1, "@fushat", kolonatString, ParameterDirection.Input);
                    break;
                case "M_CRM":
                    emriSp = "PivotGrid_CRM";
                    dbManager.CreateParameters(2);
                    dbManager.AddParameters(0, "@IDNDERMARJE", idNdermarje, ParameterDirection.Input);
                    dbManager.AddParameters(1, "@fushat", kolonatString, ParameterDirection.Input);
                    break;

                case "M_BURIME_NJEREZORE":
                    string salt = System.Web.Configuration.WebConfigurationManager.AppSettings["salt"];

                    emriSp = (kodKubi.ToLowerInvariant().Contains("lastvalues") || kodKubi.ToLowerInvariant().Contains("vlerafundit")) ? "PivotGrid_Listpagesa_vleratEFundit" : "PivotGrid_Listpagesa";
                    dbManager.CreateParameters(5);
                    dbManager.AddParameters(0, "@IDNDERMARJE", idNdermarje, ParameterDirection.Input);
                    dbManager.AddParameters(1, "@fushat", kolonatString, ParameterDirection.Input);
                    dbManager.AddParameters(2, "@salt", salt, ParameterDirection.Input);
                    dbManager.AddParameters(3, "@GJUHA", gjuha, ParameterDirection.Input);
                    dbManager.AddParameters(4, "@DATA", data, ParameterDirection.Input);
                    break;
                case "M_ANALIZE_BUXHETI":

                    emriSp = clsNdermarrje.EshteRaportuese(idNdermarje) ? "PivotGrid_Organika_raportuese" : "PivotGrid_Organika";

                    dbManager.CreateParameters(3);
                    dbManager.AddParameters(0, "@IDNDERMARRJE", idNdermarje, ParameterDirection.Input);
                    dbManager.AddParameters(1, "@fushat", kolonatString, ParameterDirection.Input);
                    dbManager.AddParameters(2, "@IDNDERMVIT", Convert.ToString(idNdermVit), ParameterDirection.Input);
                    break;

                default: return null;
            }

            return dbManager.ExecuteDataSet(CommandType.StoredProcedure, emriSp).Tables[0].DefaultView;
            //return new DataView(ds.Tables[0]);

        }

        #endregion


