        /// <param name="dtKujtese"></param>
        /// <param name="pathi"> null ne rastin kur emaili nuk eshte me atach</param>
        /// <param name="perWF">true per workflow false perndryshe</param>
        /// <returns></returns>
        private int krijoEmail(out int idEmail, int idNdermarrje, int nrProcesi, string marresEmail, DateTime dtDergimi, string subjektEmaili, string trupEmaili, statusEmail status, DateTime dtKujtese, string pathi, bool perWF, int idPerdoruesi)
        {
            idEmail = 0;

            dbManager.Open();
            dbManager.CreateParameters(12);
            dbManager.AddParameters(0, "@IDEMAIL", idEmail, ParameterDirection.Output);
            dbManager.AddParameters(1, "@IDNDERMARRJE", idNdermarrje, ParameterDirection.Input);
            dbManager.AddParameters(2, "@NRPROCESI", nrProcesi, ParameterDirection.Input);
            dbManager.AddParameters(3, "@MARRESEMAIL", marresEmail, ParameterDirection.Input);
            dbManager.AddParameters(4, "@DTDERGIMI", dtDergimi, ParameterDirection.Input);
            dbManager.AddParameters(5, "@SUBJEKTEMAILI", subjektEmaili, ParameterDirection.Input);
            dbManager.AddParameters(6, "@TRUPEMAILI", trupEmaili, ParameterDirection.Input);
            dbManager.AddParameters(7, "@STATUS", (int)status, ParameterDirection.Input);
            dbManager.AddParameters(8, "@DTKUJTESE", dtKujtese, ParameterDirection.Input);
            dbManager.AddParameters(9, "@pathi", pathi, ParameterDirection.Input);
            dbManager.AddParameters(10, "@perWF", perWF, ParameterDirection.Input);
            if (idPerdoruesi <= 0)
                dbManager.AddParameters(11, "@idPerdoruesi", DBNull.Value, ParameterDirection.Input);
            else
                dbManager.AddParameters(11, "@idPerdoruesi", idPerdoruesi, ParameterDirection.Input);
            dbManager.ExecuteNonQuery(CommandType.StoredProcedure, "prc_T_EMAIL_ins");
            idEmail = int.Parse(dbManager.Parameters[0].Value.ToString());
            return idEmail;

        }
