            dbManager.ExecuteDataSet(CommandType.Text, $"DECLARE @idndermarja INT = {idNderm};\r\n\r\n\r\n\r\nif not exists (\r\nselect * from T_LLOGARI where NRLLOGARI in (select new from llogarite_kode$ ) and IDNDERMARJE=@idndermarja\r\nand NRLLOGARI not in (select [llogarite e vjetra] from llogarite_kode$) and T_LLOGARI.IDSTATUSDOK=1\r\n)\r\nbegin\r\n\r\n\r\nupdate T_LLOGARI\r\nset NRLLOGARI=(select new from \r\nllogarite_kode$ where [llogarite e vjetra]=T_LLOGARI.NRLLOGARI and IDNDERMARJE=@idndermarja\r\n\r\n)\r\nwhere NRLLOGARI\r\n--='101601'\r\n in (select  [llogarite e vjetra] from llogarite_kode$)  and IDNDERMARJE=@idndermarja\r\n end\r\n else   PRINT N'Ka llogari ekzistuese me te njejtin kod me llogarite e reja per ndermarjen'+STR(@idndermarja);\r\n DROP TABLE llogarite_kode$");
        }

