        internal int ktheIdRaportDesignKokaBuxheti(int idBuxhetiKoka)
        {
            dbManager.Open();
            dbManager.CreateParameters(1);
            dbManager.AddParameters(0, "@IDBUXHETIKOKA", idBuxhetiKoka, ParameterDirection.Input);
            return Convert.ToInt32(dbManager.ExecuteScalar(CommandType.StoredProcedure, "prc_T_B_KOKABUXHETI_merrIdRaportDesign"));
        }
